import { createAdminClient, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { syncInventoryJob } from '../_shared/amazon/inventory.ts';

function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});}

Deno.serve(async(req:Request)=>{
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    requireInternalSecret(req);
    const body=await req.json().catch(()=>({}));
    if(!body?.job)return response({error:'Falta el job de inventario.'},400);
    const rowsProcessed=await syncInventoryJob(createAdminClient(),body.job);
    return response({ok:true,rowsProcessed});
  }catch(error){return response({error:error instanceof Error?error.message:'No se pudo sincronizar el inventario FBA.'},500);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import { spApiRequest } from './sp-api.ts';
import { loadAmazonSpApiCredentials } from './config.ts';

function quantity(value:unknown){const parsed=Number(value);return Number.isFinite(parsed)?Math.max(0,Math.trunc(parsed)):0;}

export function normalizeInventorySummary(summary:any,job:any){
  const details=summary?.inventoryDetails||{};
  return {
    owner_id:job.owner_id,
    amazon_account_id:job.amazon_account_id,
    marketplace_id:String(job.marketplace_id||''),
    seller_sku:String(summary?.sellerSku||''),
    asin:summary?.asin?String(summary.asin):null,
    fulfillable_quantity:quantity(details?.fulfillableQuantity),
    inbound_working_quantity:quantity(details?.inboundWorkingQuantity),
    inbound_shipped_quantity:quantity(details?.inboundShippedQuantity),
    inbound_receiving_quantity:quantity(details?.inboundReceivingQuantity),
    reserved_quantity:quantity(details?.reservedQuantity?.totalReservedQuantity),
    unfulfillable_quantity:quantity(details?.unfulfillableQuantity?.totalUnfulfillableQuantity),
    researching_quantity:quantity(details?.researchingQuantity?.totalResearchingQuantity),
    total_quantity:quantity(summary?.totalQuantity),
    synced_at:new Date().toISOString(),
    updated_at:new Date().toISOString(),
  };
}

function dailySnapshot(row:any,date:string){
  return {
    owner_id:row.owner_id,
    amazon_account_id:row.amazon_account_id,
    marketplace_id:row.marketplace_id,
    seller_sku:row.seller_sku,
    asin:row.asin,
    snapshot_date:date,
    fulfillable_quantity:row.fulfillable_quantity,
    inbound_quantity:row.inbound_working_quantity+row.inbound_shipped_quantity+row.inbound_receiving_quantity,
    reserved_quantity:row.reserved_quantity,
    unfulfillable_quantity:row.unfulfillable_quantity,
    researching_quantity:row.researching_quantity,
    total_quantity:row.total_quantity,
    synced_at:row.synced_at,
    updated_at:row.updated_at,
  };
}

async function persistInventoryPage(admin:any,summaries:any[],job:any){
  const currentRows=summaries
    .filter(summary=>String(summary?.sellerSku||'').trim())
    .map(summary=>normalizeInventorySummary(summary,job));
  if(!currentRows.length)return 0;
  const {error:currentError}=await admin.from('amazon_inventory_current').upsert(currentRows,{onConflict:'owner_id,amazon_account_id,marketplace_id,seller_sku'});
  if(currentError)throw currentError;
  const snapshotDate=new Date().toISOString().slice(0,10);
  const dailyRows=currentRows.map(row=>dailySnapshot(row,snapshotDate));
  const {error:dailyError}=await admin.from('amazon_inventory_daily').upsert(dailyRows,{onConflict:'owner_id,amazon_account_id,marketplace_id,seller_sku,snapshot_date'});
  if(dailyError)throw dailyError;
  return currentRows.length;
}

export async function syncInventoryJob(admin:any,job:any){
  if(!job?.marketplace_id)throw new Error('Job de inventario incompleto.');
  const credentials=await loadAmazonSpApiCredentials(admin,{amazonAccountId:job.amazon_account_id,ownerId:job.owner_id});
  let nextToken:string|undefined;
  let processed=0;
  do{
    const query:any={
      details:true,
      granularityType:'Marketplace',
      granularityId:job.marketplace_id,
      marketplaceIds:[job.marketplace_id],
      ...(nextToken?{nextToken}:{}),
    };
    const data:any=await spApiRequest('/fba/inventory/v1/summaries',{query},credentials);
    const summaries=Array.isArray(data?.payload?.inventorySummaries)?data.payload.inventorySummaries:[];
    processed+=await persistInventoryPage(admin,summaries,job);
    nextToken=data?.pagination?.nextToken||undefined;
  }while(nextToken);
  return processed;
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}
